package com.marketplace.payment;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.mongodb.repository.MongoRepository; import org.springframework.http.*; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.net.URI; import java.time.Instant;
interface PaymentRepository extends JpaRepository<Payment,Long>{} interface AuditLogRepository extends MongoRepository<AuditLog,String>{} @RestController @RequestMapping("/api/payments") class PaymentController { private final PaymentRepository payments;private final AuditLogRepository audits;PaymentController(PaymentRepository p,AuditLogRepository a){payments=p;audits=a;}record Request(@NotNull @Positive Long orderId,@NotNull @Positive BigDecimal amount){}@PostMapping @Transactional ResponseEntity<Payment> create(@Valid @RequestBody Request r){var p=payments.save(new Payment(r.orderId(),r.amount()));audits.save(new AuditLog(null,p.id,"PAYMENT_CREATED",Instant.now()));return ResponseEntity.created(URI.create("/api/payments/"+p.id)).body(p);}@PostMapping("/{id}/confirm") @Transactional Payment confirm(@PathVariable Long id){var p=payments.findById(id).orElseThrow();p.status="PAID";p=payments.save(p);audits.save(new AuditLog(null,p.id,"PAYMENT_CONFIRMED",Instant.now()));return p;} }
